var a=`0863-gajar-ka-halwa`;var t=`world-0863`;var s=`IN`;var n=`south-asia`;var o=8;var r=77;var g={en:`Gajar ka Halwa`,ua:`Гаджар ка халва`};var l={en:`Gajar ka Halwa is a India dish made with carrot, whole cow milk, cashew, pistachio. This home-scale recipe assigns measured ingredients to the steps where they are used.`,ua:`Гаджар ка халва, страва кухні країни Індія. Основні складники: морква, цільне коров'яче молоко, кеш'ю, фісташка. Кількості у цьому домашньому рецепті прив’язані до відповідних етапів.`};var h=[{en:`Peel and coarsely grate the listed vegetables; squeeze out excess moisture so the mixture will hold together.`,ua:`Очистьте й натріть овочі на грубій тертці; відіжміть зайву рідину, щоб маса тримала форму.`,t:[`peeling`,`coarse-grating`,`squeezing-out-moisture`],m:10,i:[[`carrot`,800,`g`]]},{en:`Slowly cook grated carrot in milk and ghee, stirring often, until the carrot is soft and most milk has evaporated.`,ua:`Повільно варіть терту моркву в молоці з гхі, часто помішуючи, до м’якості моркви й випаровування більшості молока.`,t:[`reducing-sauce`],m:50,i:[[`whole-cow-milk`,650,`ml`],[`ghee`,75,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:14,i:[[`white-granulated-sugar`,140,`g`],[`ground-cardamom`,5,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cashew`,65,`g`],[`pistachio`,25,`g`]]}];var d={slug:a,id:t,country:`IN`,region:n,servings:8,minutes:77,title:g,text:l,steps:h};export{s as country,d as default,t as id,r as minutes,n as region,o as servings,a as slug,h as steps,l as text,g as title};